text:
🎛️ Interactive: Free Damped Response Explorer
Explore how the damping ratio \(\zeta\) and initial conditions shape the free vibration response. Watch the transition between underdamped, critically damped, and overdamped behaviour.


Code
viewof zeta5 = Inputs.range([0.01, 2.5], {value: 0.1, step: 0.01, label: "Damping ratio  ζ"})
viewof wn5   = Inputs.range([0.5, 20],   {value: 5.0, step: 0.5,  label: "Natural frequency  ωₙ  (rad/s)"})
viewof u0_5  = Inputs.range([-3, 3],     {value: 1.0, step: 0.1,  label: "Initial displacement  u₀  (m)"})
viewof v0_5  = Inputs.range([-15, 15],   {value: 0.0, step: 0.5,  label: "Initial velocity  v₀  (m/s)"})
viewof show_envelope = Inputs.toggle({label: "Show decay envelope", value: true})







































Code
regime5 = zeta5 &lt; 0.999 ? "underdamped" : (zeta5 &lt; 1.001 ? "critical" : "overdamped")

// Time setup
tEnd5 = Math.max(5 * 2*Math.PI / Math.max(wn5 * Math.sqrt(Math.abs(1 - zeta5**2)), 0.1), 8 / (zeta5 * wn5))
tEnd5c = Math.min(tEnd5, 60)
dt5 = tEnd5c / 800

// Response function
function u5(t) {
  if (regime5 === "underdamped") {
    let wd = wn5 * Math.sqrt(1 - zeta5**2)
    let A5 = u0_5
    let B5 = (v0_5 + zeta5 * wn5 * u0_5) / wd
    return Math.exp(-zeta5 * wn5 * t) * (A5 * Math.cos(wd * t) + B5 * Math.sin(wd * t))
  } else if (regime5 === "critical") {
    let A5 = u0_5
    let B5 = v0_5 + wn5 * u0_5
    return (A5 + B5 * t) * Math.exp(-wn5 * t)
  } else {
    let sq = wn5 * Math.sqrt(zeta5**2 - 1)
    let s1 = -zeta5*wn5 + sq, s2 = -zeta5*wn5 - sq
    let A5 = (v0_5 - s2 * u0_5) / (s1 - s2)
    let B5 = u0_5 - A5
    return A5 * Math.exp(s1 * t) + B5 * Math.exp(s2 * t)
  }
}

function env5(t) {
  let V5 = Math.sqrt(u0_5**2 + ((v0_5 + zeta5*wn5*u0_5)/Math.max(wn5*Math.sqrt(1-zeta5**2),0.01))**2)
  return V5 * Math.exp(-zeta5 * wn5 * t)
}

t_arr5 = Array.from({length: 801}, (_, i) =&gt; i * dt5)
data5 = t_arr5.map(t =&gt; ({t, u: u5(t)}))
data5env_pos = (show_envelope && regime5 === "underdamped")
  ? t_arr5.map(t =&gt; ({t, y: env5(t)})) : []
data5env_neg = (show_envelope && regime5 === "underdamped")
  ? t_arr5.map(t =&gt; ({t, y: -env5(t)})) : []

// Logarithmic decrement (for underdamped)
delta5 = regime5 === "underdamped" ? 2 * Math.PI * zeta5 / Math.sqrt(1 - zeta5**2) : NaN
wd5 = regime5 === "underdamped" ? wn5 * Math.sqrt(1 - zeta5**2) : NaN
Td5 = regime5 === "underdamped" ? 2 * Math.PI / wd5 : NaN































































































Code
html`
&lt;div style="display:flex;gap:1.2rem;flex-wrap:wrap;margin:0.4rem 0 1rem 0;font-size:0.93em;background:#f8f9fa;padding:0.6rem 1rem;border-radius:6px"&gt;
  &lt;span&gt;Regime: &lt;strong style="color:${regime5==='underdamped'?'#1a6faf':regime5==='critical'?'#27ae60':'#c0392b'}"&gt;${regime5.charAt(0).toUpperCase()+regime5.slice(1)}&lt;/strong&gt;&lt;/span&gt;
  ${regime5==="underdamped" ? html`
    &lt;span&gt;ω_d = &lt;strong&gt;${wd5.toFixed(3)} rad/s&lt;/strong&gt;&lt;/span&gt;
    &lt;span&gt;T_d = &lt;strong&gt;${Td5.toFixed(3)} s&lt;/strong&gt;&lt;/span&gt;
    &lt;span&gt;δ = &lt;strong&gt;${delta5.toFixed(4)}&lt;/strong&gt;&lt;/span&gt;
    &lt;span&gt;ζ (from δ) ≈ &lt;strong&gt;${(delta5/(2*Math.PI)).toFixed(4)}&lt;/strong&gt;&lt;/span&gt;
  ` : html``}
&lt;/div&gt;`









Code
Plot.plot({
  title: `Free Damped Response — ${regime5.charAt(0).toUpperCase()+regime5.slice(1)} (ζ = ${zeta5.toFixed(2)})`,
  marks: [
    Plot.ruleY([0], {stroke: "#ccc"}),
    ...(show_envelope && regime5 === "underdamped" ? [
      Plot.line(data5env_pos, {x: "t", y: "y", stroke: "#c0392b", strokeWidth: 1.5, strokeDasharray: "6,4"}),
      Plot.line(data5env_neg, {x: "t", y: "y", stroke: "#c0392b", strokeWidth: 1.5, strokeDasharray: "6,4"})
    ] : []),
    Plot.line(data5, {
      x: "t", y: "u",
      stroke: regime5 === "underdamped" ? "#1a6faf" : (regime5 === "critical" ? "#27ae60" : "#c0392b"),
      strokeWidth: 2.8
    }),
    Plot.dot([{t: 0, u: u0_5}], {x: "t", y: "u", fill: "#e67e22", r: 6})
  ],
  x: {label: "Time  t  (s)", grid: true},
  y: {label: "Displacement  u(t)  (m)", grid: true},
  width: 700, height: 340,
  style: {fontSize: "13px"}
})








Explore the three regimes:

Underdamped (\(\zeta &lt; 1\)): Set \(\zeta = 0.05\)–\(0.3\). The system oscillates at \(\omega_d &lt; \omega_n\), with an exponentially decaying envelope. The smaller \(\zeta\), the longer it takes to settle.
Critically damped (\(\zeta \approx 1\)): The system returns to zero the fastest possible without crossing the axis. Look for the zero crossing near \(t = 1/\omega_n\).
Overdamped (\(\zeta &gt; 1\)): Two real decay rates give a sluggish, non-oscillatory return. Very large \(\zeta\) makes the system extremely slow.
Toggle envelope: For underdamped response, the dashed red lines show the exponential decay envelope \(\pm Ve^{-\zeta\omega_n t}\).

🎛️ Interactive: Forced Undamped Response Explorer
Use the sliders to explore directly the equations derived above. The amplitude \(U = F_0/(k - m\omega^2)\) and the time response \(u_p(t) = U\sin(\omega t)\) are plotted in physical units — no normalisation.


Code
viewof m3 = Inputs.range([0.1, 20],  {value: 2.0,  step: 0.1, label: "Mass  m  (kg)"})
viewof k3 = Inputs.range([1, 1000],  {value: 200,  step: 1,   label: "Stiffness  k  (N/m)"})
viewof F0_3 = Inputs.range([0.1, 50], {value: 10.0, step: 0.1, label: "Force amplitude  F₀  (N)"})
viewof omega_exc = Inputs.range([0.1, 40], {value: 5.0, step: 0.1, label: "Excitation frequency  ω  (rad/s)"})
































Code
wn3 = Math.sqrt(k3 / m3)

// Amplitude from the derived equation: U = F0 / (k - m*omega^2)
denom3 = k3 - m3 * omega_exc**2
U3_signed = F0_3 / denom3          // signed (negative = 180° phase flip)
U3_abs    = Math.abs(U3_signed)
phase3_deg = denom3 &gt; 0 ? 0 : 180

// Frequency response curve: |U| vs omega, skip near resonance
omega_max3 = Math.max(2.5 * wn3, omega_exc * 1.3, 15)
omega_pts3 = Array.from({length: 700}, (_, i) =&gt; {
  let w  = 0.05 + i * (omega_max3 - 0.05) / 699
  let D  = k3 - m3 * w**2
  if (Math.abs(D) &lt; 0.3) return null
  let U  = Math.abs(F0_3 / D)
  if (U &gt; 0.5)  return null          // clip for readability
  return {omega: w, U, sign: D &gt; 0 ? "below" : "above"}
}).filter(d =&gt; d !== null)

// Phase curve (step: 0° below ωn, 180° above)
phase_pts3 = Array.from({length: 700}, (_, i) =&gt; {
  let w = 0.05 + i * (omega_max3 - 0.05) / 699
  let D = k3 - m3 * w**2
  return {omega: w, phase: D &gt; 0 ? 0 : 180}
})

// Time domain — fixed 20 s window
dt3 = 20 / 600
data_time3 = Array.from({length: 601}, (_, i) =&gt; ({
  t: i * dt3,
  u: U3_signed * Math.sin(omega_exc * i * dt3)
}))










































































Code
html`
&lt;div style="display:flex;gap:1.8rem;flex-wrap:wrap;margin:0.4rem 0 1rem 0;font-size:0.93em;color:#333;background:#f8f9fa;padding:0.6rem 1.1rem;border-radius:6px"&gt;
  &lt;span&gt;𝜔ₙ = &lt;strong&gt;${wn3.toFixed(3)} rad/s&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;k − mω² = &lt;strong style="color:${Math.abs(denom3) &lt; 5 ? '#c0392b' : '#333'}"&gt;${denom3.toFixed(2)} N/m&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;|U| = &lt;strong style="color:${U3_abs &gt; 0.2 ? '#c0392b' : '#1a4a7a'}"&gt;${U3_abs &gt; 0.49 ? '→ ∞' : (U3_abs*1000).toFixed(2) + ' mm'}&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;Phase = &lt;strong&gt;${phase3_deg}°&lt;/strong&gt;&lt;/span&gt;
&lt;/div&gt;`









Code
// Frequency response: |U| (m) vs omega (rad/s)
Plot.plot({
  title: "Amplitude  |U|  vs  Excitation Frequency  ω",
  marks: [
    Plot.ruleY([0], {stroke: "#ddd"}),
    // ωn vertical marker
    Plot.ruleX([wn3], {stroke: "#e67e22", strokeDasharray: "6,4", strokeWidth: 1.8}),
    Plot.text([{omega: wn3, U: 0.45}], {
      x: "omega", y: "U",
      text: d =&gt; `ωₙ = ${wn3.toFixed(2)}`,
      fontSize: 11, fill: "#e67e22", dx: 4
    }),
    Plot.line(omega_pts3.filter(d =&gt; d.sign === "below"), {
      x: "omega", y: "U", stroke: "#1a6faf", strokeWidth: 2.5
    }),
    Plot.line(omega_pts3.filter(d =&gt; d.sign === "above"), {
      x: "omega", y: "U", stroke: "#c0392b", strokeWidth: 2.5
    }),
    Plot.dot([{omega: omega_exc, U: Math.min(U3_abs, 0.49)}], {
      x: "omega", y: "U", fill: "#e67e22", r: 7
    })
  ],
  x: {label: "ω  (rad/s)", grid: true},
  y: {label: "|U|  (m)", domain: [0, 0.5], grid: true},
  width: 680, height: 280,
  style: {fontSize: "13px"}
})









Code
// Phase angle vs omega (step function: 0° below wn, 180° above)
Plot.plot({
  title: "Phase Angle vs Excitation Frequency  ω",
  marks: [
    Plot.ruleX([wn3], {stroke: "#e67e22", strokeDasharray: "6,4", strokeWidth: 1.8}),
    Plot.text([{omega: wn3, phase: 90}], {
      x: "omega", y: "phase",
      text: d =&gt; `ωₙ = ${wn3.toFixed(2)}`,
      fontSize: 11, fill: "#e67e22", dx: 4
    }),
    Plot.line(phase_pts3, {x: "omega", y: "phase", stroke: "#1a6faf", strokeWidth: 2.5}),
    Plot.dot([{omega: omega_exc, phase: phase3_deg}], {
      x: "omega", y: "phase", fill: "#e67e22", r: 7
    })
  ],
  x: {label: "ω  (rad/s)", grid: true},
  y: {label: "Phase (°)", domain: [-15, 195], ticks: [0, 90, 180], grid: true},
  width: 680, height: 200,
  style: {fontSize: "13px"}
})









Code
// Time domain response
Plot.plot({
  title: `Time Response  u_p(t) = U·sin(ωt)   [U = ${(U3_signed*1000).toFixed(2)} mm,  phase = ${phase3_deg}°]`,
  marks: [
    Plot.ruleY([0], {stroke: "#ddd"}),
    Plot.line(data_time3, {x: "t", y: "u", stroke: "#1a6faf", strokeWidth: 2.5})
  ],
  x: {label: "Time  t  (s)", grid: true},
  y: {label: "u_p(t)  (m)", grid: true},
  width: 680, height: 260,
  style: {fontSize: "13px"}
})








Try this: Increase \(\omega\) toward \(\omega_n\) and watch \(|U|\) grow unboundedly — the denominator \(k - m\omega^2\) approaches zero. Cross \(\omega_n\) and the denominator flips sign: \(U\) becomes negative (phase = 180°, the mass moves opposite to the force). Increasing \(k\) or decreasing \(m\) shifts \(\omega_n\) to the right.

🎛️ Interactive: Free Vibration Explorer
Use the sliders below to explore how mass \(m\), stiffness \(k\), and initial conditions affect the free vibration response \(u(t) = A\sin(\omega_n t + \phi)\).


Code
viewof m_val  = Inputs.range([0.1, 10],  {value: 1.0, step: 0.1, label: "Mass  m  (kg)"})
viewof k_val  = Inputs.range([1, 200],   {value: 20,  step: 1,   label: "Stiffness  k  (N/m)"})
viewof u0_val = Inputs.range([-3, 3],    {value: 1.0, step: 0.1, label: "Initial displacement  u₀  (m)"})
viewof v0_val = Inputs.range([-10, 10],  {value: 0.0, step: 0.5, label: "Initial velocity  v₀  (m/s)"})
































Code
wn     = Math.sqrt(k_val / m_val)
Tn     = 2 * Math.PI / wn
fn     = wn / (2 * Math.PI)
phi_ic = Math.atan2(u0_val * wn, v0_val)
A_amp  = Math.sqrt(u0_val**2 + (v0_val / wn)**2)

// Fixed 30 s time window — curve changes shape, axis stays constant
data_free = Array.from({length: 901}, (_, i) =&gt; ({
  t: i * 30 / 900,
  u: A_amp * Math.sin(wn * i * 30 / 900 + phi_ic)
}))














































Code
html`
&lt;div style="display:flex;gap:2rem;flex-wrap:wrap;margin:0.5rem 0 1rem 0;font-size:0.93em;color:#333;background:#f8f9fa;padding:0.6rem 1.1rem;border-radius:6px"&gt;
  &lt;span&gt;𝜔ₙ = &lt;strong&gt;${wn.toFixed(3)} rad/s&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;fₙ = &lt;strong&gt;${fn.toFixed(3)} Hz&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;Tₙ = &lt;strong&gt;${Tn.toFixed(3)} s&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;A = &lt;strong&gt;${A_amp.toFixed(3)} m&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;𝜙 = &lt;strong&gt;${(phi_ic * 180 / Math.PI).toFixed(1)}°&lt;/strong&gt;&lt;/span&gt;
&lt;/div&gt;`









Code
Plot.plot({
  marks: [
    Plot.ruleY([0], {stroke: "#ccc"}),
    Plot.line(data_free, {
      x: "t", y: "u",
      stroke: "#1a6faf", strokeWidth: 2.5
    }),
    Plot.dot([{t: 0, u: u0_val}], {x: "t", y: "u", fill: "#c0392b", r: 6})
  ],
  x: {label: "Time  t  (s)", domain: [0, 30], grid: true},
  y: {label: "Displacement  u(t)  (m)", grid: true},
  width: 700, height: 320,
  style: {fontSize: "13px"}
})








Try this: Set \(v_0 = 0\) and vary \(u_0\) — you get a pure sine with amplitude \(A = u_0\). Set \(u_0 = 0\) and vary \(v_0\) — you get a sine shifted by 90°. Increase \(k\) or decrease \(m\) to raise \(\omega_n\) and see more oscillations within the 30 s windo

🎛️ Interactive: Bode Plot Explorer
The frequency response plots (amplitude and phase vs. \(r\)) are known as Bode plots in control engineering and frequency response functions in structural dynamics. Use the controls below to explore how the damping ratio \(\zeta\) shapes the response.


Code
viewof zeta_val = Inputs.range([0.01, 2.0], {value: 0.1, step: 0.01, label: "Damping ratio  ζ"})
viewof show_multi = Inputs.toggle({label: "Show multiple ζ curves", value: false})


















Code
function ampRatio(r, zeta) {
  return 1 / Math.sqrt((1 - r**2)**2 + (2*zeta*r)**2)
}
function phaseAngle(r, zeta) {
  let phi = Math.atan2(2*zeta*r, 1 - r**2) * 180 / Math.PI
  if (phi &lt; 0) phi += 180
  return phi
}

r_pts = Array.from({length: 800}, (_, i) =&gt; 0.01 + i * (2.99 / 799))

// Single curve data
data_amp = r_pts.map(r =&gt; ({r, y: ampRatio(r, zeta_val)}))
data_phase = r_pts.map(r =&gt; ({r, y: phaseAngle(r, zeta_val)}))

// Multi-curve data
zeta_list = [0.05, 0.1, 0.2, 0.3, 0.5, 0.7, 1.0]
colors_zeta = ["#c0392b","#e67e22","#f1c40f","#27ae60","#1a6faf","#8e44ad","#555"]
data_multi_amp = zeta_list.flatMap((z, i) =&gt;
  r_pts.map(r =&gt; ({r, y: Math.min(ampRatio(r, z), 15), zeta: z, color: colors_zeta[i]}))
)
data_multi_phase = zeta_list.flatMap((z, i) =&gt;
  r_pts.map(r =&gt; ({r, y: phaseAngle(r, z), zeta: z, color: colors_zeta[i]}))
)



































































Code
html`
&lt;div style="display:flex;gap:1.5rem;flex-wrap:wrap;margin:0.4rem 0 1rem 0;font-size:0.93em;color:#333;background:#f8f9fa;padding:0.6rem 1rem;border-radius:6px"&gt;
  &lt;span&gt;ζ = &lt;strong&gt;${zeta_val.toFixed(2)}&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;Peak |U/u_st| = &lt;strong&gt;${(1/(2*zeta_val*Math.sqrt(1-zeta_val**2))).toFixed(2)} &lt;/strong&gt;${zeta_val &lt; 1/Math.sqrt(2) ? '@ r ≈ ' + Math.sqrt(1 - 2*zeta_val**2).toFixed(3) : '(no peak for ζ ≥ 1/√2)'}&lt;/span&gt;
  &lt;span&gt;At r=1: &lt;strong&gt;${(1/(2*zeta_val)).toFixed(2)}&lt;/strong&gt;&lt;/span&gt;
  &lt;span&gt;Regime: &lt;strong style="color:${zeta_val &lt; 1 ? '#1a6faf' : zeta_val === 1 ? '#27ae60' : '#c0392b'}"&gt;${zeta_val &lt; 1 ? 'Underdamped' : zeta_val === 1 ? 'Critical' : 'Overdamped'}&lt;/strong&gt;&lt;/span&gt;
&lt;/div&gt;`









Code
// Amplitude plot
Plot.plot({
  title: "Amplitude Ratio  |U / u_st|  vs  Frequency Ratio  r",
  marks: [
    Plot.ruleY([0], {stroke: "#eee"}),
    Plot.ruleX([1], {stroke: "#ccc", strokeDasharray: "5,4"}),
    ...(show_multi
      ? zeta_list.map((z, i) =&gt;
          Plot.line(data_multi_amp.filter(d =&gt; d.zeta === z), {
            x: "r", y: "y", stroke: colors_zeta[i], strokeWidth: 1.6,
            strokeOpacity: z === zeta_val ? 1.0 : 0.4
          })
        )
      : []),
    Plot.line(show_multi ? data_multi_amp.filter(d =&gt; d.zeta === zeta_val) : data_amp, {
      x: "r", y: show_multi ? "y" : "y",
      stroke: "#1a4a7a", strokeWidth: show_multi ? 3.0 : 2.8
    }),
    Plot.dot([{r: 1.0, y: 1/(2*zeta_val)}], {x: "r", y: "y", fill: "#e67e22", r: 6})
  ],
  x: {label: "r = ω / ωₙ", domain: [0, 3], grid: true},
  y: {label: "|U| / u_st", domain: [0, Math.min(12, 1/(2*zeta_val) * 1.3 + 1)], grid: true},
  width: 700, height: 300,
  style: {fontSize: "13px"}
})









Code
// Phase plot
Plot.plot({
  title: "Phase Angle  φ  vs  Frequency Ratio  r",
  marks: [
    Plot.ruleY([0, 90, 180], {stroke: "#eee"}),
    Plot.ruleX([1], {stroke: "#ccc", strokeDasharray: "5,4"}),
    ...(show_multi
      ? zeta_list.map((z, i) =&gt;
          Plot.line(data_multi_phase.filter(d =&gt; d.zeta === z), {
            x: "r", y: "y", stroke: colors_zeta[i], strokeWidth: 1.6,
            strokeOpacity: z === zeta_val ? 1.0 : 0.4
          })
        )
      : []),
    Plot.line(show_multi ? data_multi_phase.filter(d =&gt; d.zeta === zeta_val) : data_phase, {
      x: "r", y: show_multi ? "y" : "y",
      stroke: "#c0392b", strokeWidth: show_multi ? 3.0 : 2.8
    }),
    Plot.dot([{r: 1.0, y: 90}], {x: "r", y: "y", fill: "#e67e22", r: 6})
  ],
  x: {label: "r = ω / ωₙ", domain: [0, 3], grid: true},
  y: {label: "Phase φ (degrees)", domain: [0, 185], ticks: [0, 45, 90, 135, 180], grid: true},
  width: 700, height: 260,
  style: {fontSize: "13px"}
})









Code
show_multi ? html`
&lt;div style="display:flex;gap:1.2rem;flex-wrap:wrap;font-size:0.82em;margin-top:0.4rem"&gt;
  ${zeta_list.map((z,i) =&gt; html`&lt;span&gt;&lt;span style="color:${colors_zeta[i]};font-weight:bold"&gt;—&lt;/span&gt; ζ = ${z}&lt;/span&gt;`)}
&lt;/div&gt;` : html``








Key observations: - As \(\zeta\) decreases, the resonant peak grows sharper and taller. - At \(r = 1\) (resonance), the phase is always 90°, regardless of \(\zeta\). - For \(\zeta \geq 1/\sqrt{2} \approx 0.707\), the amplitude ratio has no peak above the static value. - Toggle “Show multiple ζ curves” to compare responses across damping levels simultaneously.

🎛️ Interactive: Transmissibility Explorer
Explore how the damping ratio \(\zeta\) and frequency ratio \(r\) shape both the force transmissibility \(T_F\) (= absolute motion transmissibility \(X/Y\)) and the relative displacement ratio \(U/Y\). The dashed vertical line marks the isolation threshold \(r = \sqrt{2}\).


Code
viewof zeta6    = Inputs.range([0.01, 1.5],  {value: 0.15, step: 0.01,  label: "Damping ratio  ζ"})
viewof show_multi6   = Inputs.toggle({label: "Show multiple ζ curves", value: false})
viewof show_rel6     = Inputs.toggle({label: "Show relative displacement  U/Y", value: true})
viewof r_op6    = Inputs.range([0.01, 3.5],  {value: 0.7,  step: 0.01,  label: "Operating point  r = ω/ωₙ"})
































Code
function TF6(r, zeta) {
  return Math.sqrt(1 + (2*zeta*r)**2) / Math.sqrt((1-r**2)**2 + (2*zeta*r)**2)
}
function relDisp6(r, zeta) {
  return r**2 / Math.sqrt((1-r**2)**2 + (2*zeta*r)**2)
}

r6_pts = Array.from({length: 900}, (_, i) =&gt; {
  let r = 0.01 + i * (3.49 / 899)
  return r
})

// Single-curve data
data6_TF  = r6_pts.map(r =&gt; ({r, y: Math.min(TF6(r, zeta6), 14)}))
data6_rel = r6_pts.map(r =&gt; ({r, y: Math.min(relDisp6(r, zeta6), 14)}))

// Multi-curve data
zeta6_list   = [0.05, 0.1, 0.2, 0.3, 0.5, 0.7, 1.0]
